{
  "title": "Facebook Group Profile Scraper",
  "description": "Choose Direct group URL, Group username, or Numeric group ID. Add one or more groups to the matching list. Other lists are ignored.\n\nNeed a fix or improvement? [File an issue](https://apify.com/maximedupre/facebook-group-profile-scraper/issues/open) and I'll resolve it in less than 24h 🫡",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "findGroupsBy": {
      "title": "Find groups by",
      "type": "string",
      "description": "Choose how you will provide the public Facebook groups. Add values only to the matching list; other lists are ignored.",
      "editor": "select",
      "enum": [
        "url",
        "username",
        "id"
      ],
      "enumTitles": [
        "Direct group URL",
        "Group username",
        "Numeric group ID"
      ],
      "prefill": "url"
    },
    "groupUrls": {
      "title": "Group URLs",
      "type": "array",
      "description": "Add one or more direct URLs for public Facebook groups. The Actor saves a profile for each group it can resolve.",
      "editor": "requestListSources",
      "prefill": [
        {
          "url": "https://www.facebook.com/groups/1010440649638729"
        }
      ],
      "items": {
        "type": "object",
        "properties": {
          "url": {
            "title": "Group URL",
            "type": "string",
            "description": "A direct URL for a public Facebook group."
          }
        },
        "required": [
          "url"
        ]
      },
      "sectionCaption": "🔗 Direct group URL options"
    },
    "groupUsernames": {
      "title": "Group usernames",
      "type": "array",
      "description": "Add one or more Facebook group usernames without the @ sign. The Actor saves a profile for each group it can resolve.",
      "editor": "stringList",
      "items": {
        "type": "string",
        "pattern": "^[A-Za-z0-9][A-Za-z0-9._-]*$"
      },
      "sectionCaption": "👤 Group username options"
    },
    "groupIds": {
      "title": "Numeric group IDs",
      "type": "array",
      "description": "Add one or more numeric Facebook group IDs. Keep each ID as a full number. The Actor saves a profile for each group it can resolve.",
      "editor": "stringList",
      "items": {
        "type": "string",
        "pattern": "^[0-9]+$"
      },
      "sectionCaption": "🔢 Numeric group ID options"
    }
  },
  "required": [
    "findGroupsBy"
  ]
}
